<?php
namespace App\Http\Controllers;
use App\Models\Membership;
use App\Services\MembershipPaymentService;
use Illuminate\Http\Request;
use Illuminate\Http\RedirectResponse;
use Illuminate\View\View;
use Illuminate\Support\Facades\Log;
use Throwable;
class MembershipController extends Controller
{
 public function show(Request $request):View|RedirectResponse{$membership=$request->user()->pelanggan?->membership;abort_unless($membership,404);$membership->load('customer.user','gatewayPayment');if(!$membership->gatewayPayment)$membership->setRelation('gatewayPayment',$membership->gatewayPayments()->latest('id_pembayaran_gateway')->first());if($membership->isActive()&&!$request->boolean('finish')){$intent=$request->session()->pull('trade_in.intent');if(is_array($intent)&&($intent['mobil']??null||($intent['slug']??null)))return redirect()->route('trade-in.entry',$intent);return redirect()->route('pelanggan.dashboard');}return view('pelanggan.membership.activation',compact('membership'));}
 public function finish(Request $request,MembershipPaymentService $service){$membership=$request->user()->pelanggan?->membership;abort_unless($membership,404);$membership->load('customer.user','gatewayPayment');$orderId=trim((string)$request->query('order_id',''));$gateway=$membership->gatewayPayment?:$membership->gatewayPayments()->latest('id_pembayaran_gateway')->first();if($orderId!==''&&$gateway&& !hash_equals((string)$gateway->order_id,$orderId)){$candidate=$membership->gatewayPayments()->where('order_id',$orderId)->first();if($candidate)$gateway=$candidate;}if(!$gateway)return redirect()->route('pelanggan.membership.activation')->withErrors('Pembayaran membership belum ditemukan. Silakan mulai pembayaran kembali.');try{$service->sync($gateway,$request->user());$membership->refresh();$intent=$membership->isActive()?$request->session()->pull('trade_in.intent'):null;if(is_array($intent)&&($intent['mobil']??null||($intent['slug']??null)))return redirect()->route('trade-in.entry',$intent);return redirect()->route('pelanggan.membership.activation',['finish'=>(int)$membership->isActive()]);}catch(Throwable $e){Log::error('YZA membership finish verification failed',['user_id'=>$request->user()->id_user,'order_id'=>$orderId,'gateway_order_id'=>$gateway->order_id,'exception'=>$e->getMessage()]);return redirect()->route('pelanggan.membership.activation')->withErrors('Status pembayaran belum dapat diverifikasi dari server. Silakan tekan Cek Status Pembayaran.');}}
 public function pay(Request $request,MembershipPaymentService $service){try{$attempt=$service->createAttempt($request->user()->pelanggan->membership,$request->user());if(!is_string($attempt->redirect_url)||trim($attempt->redirect_url)==='')throw new \RuntimeException('Midtrans Sandbox tidak mengembalikan redirect URL.');return redirect()->away($attempt->redirect_url);}catch(Throwable $e){Log::error('YZA membership payment button failed',['user_id'=>$request->user()->id_user,'exception'=>$e->getMessage()]);return back()->withErrors('Pembayaran belum dapat dibuka. Silakan coba kembali.');}}
 public function sync(Request $request,MembershipPaymentService $service){$membership=$request->user()->pelanggan?->membership;abort_unless($membership,404);$gateway=$membership->gatewayPayment?:$membership->gatewayPayments()->latest('id_pembayaran_gateway')->first();abort_unless($gateway,404);try{$service->sync($gateway,$request->user());return back()->with('status','Status pembayaran membership sudah diperiksa.');}catch(Throwable $e){return back()->withErrors($e->getMessage());}}
}
